-- Monthly community narratives (#759).
--
-- One stored LLM neighbourhood narrative per (community, YYYY-MM period),
-- generated by the monthly timer and reused by every report in that
-- community (no LLM call per estimate). Expand-only: a new table, no change
-- to existing data. The per-estimate `estimates.narrative` column stays and
-- is still read for older reports.
CREATE TABLE IF NOT EXISTS "community_narratives" (
	"community_slug" text NOT NULL,
	"period" text NOT NULL,
	"narrative" text,
	"model" text,
	"prompt_version" text NOT NULL,
	"status" text NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"last_error" text,
	"generated_at" timestamp with time zone,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "community_narratives_slug_period_pk" PRIMARY KEY("community_slug","period")
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "community_narratives_status_idx" ON "community_narratives" USING btree ("status");
